def minify(s: str) -> str:
    """Map a short lowercase token to a shorter lowercase token (used for log keys).  Note: Collisions are possible."""
    if not s:
        return ""
    # keep first and last character; collapse the middle
    return s[0] + s[-1] if len(s) > 1 else s

